#!/usr/bin/env python3
"""Build a local, searchable art gallery from the portrait inventory."""
import html,json
from pathlib import Path
root=Path(__file__).resolve().parent.parent
data=json.loads((root/'assets/portraits/inventory.json').read_text())
roles={'teller':'柜员','lobby':'大堂经理','wealth':'理财经理','cm':'客户经理'}
fallback_roles={'张秀芬':'退休客户','陈德贵':'退休客户','冉国强':'冉记老灶老板','韩冬':'对公团队负责人','杜衡':'重庆分行副行长','沈岚':'重庆分行副行长','蒋国栋':'重庆分行副行长'}
audit=data.get("leadershipAudit",{})
bank_keys=set(audit.get("redesigned",[])+audit.get("retained",[]))
cards=[]
for c in data['characters']:
 group='客户' if 'CUST_NAMES' in c['sources'] else '玩家' if 'player-avatar' in c['sources'] else '银行' if c['key'] in bank_keys else '角色'
 name=html.escape(c['name']);role=html.escape(roles.get(c['role'],c['role']) or fallback_roles.get(c['name'],'银行同事'));note=html.escape(c.get('note',''))
 src='assets/portraits/web/'+c['key']+'-l.webp'
 cards.append(f'<button class="card" data-group="{group}" data-name="{name}" data-role="{role}" data-note="{note}"><div class="art"><img src="{src}" alt="{name}立绘" loading="lazy" decoding="async"></div><div class="info"><h2>{name}</h2><p>{role}</p></div></button>')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>银行升职记 · 人物立绘</title><style>
:root{color-scheme:light;--ink:#16302b;--paper:#f3f0e8;--gold:#9c8050}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,-apple-system,sans-serif}header{padding:34px max(20px,calc((100% - 1200px)/2));background:var(--ink);color:#f9f7ef}h1{margin:0 0 9px;font-family:Songti SC,serif;font-size:28px}header p{margin:0;color:#c6cfbf;font-size:13px}nav{display:flex;gap:10px;flex-wrap:wrap;align-items:center;max-width:1200px;margin:24px auto 16px;padding:0 16px}input,select,nav a{font:inherit;border:1px solid #d8d3c7;background:#fffdf7;color:var(--ink);padding:11px 14px;border-radius:8px}input{flex:1;min-width:140px}nav a{text-decoration:none;font-size:13px}#count{font-size:13px;color:#6d756b;margin-left:auto}main{max-width:1200px;margin:auto;padding:0 16px 40px;display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:16px}.card{border:1px solid #ddd6c7;border-radius:12px;background:#fffdf8;padding:0;overflow:hidden;cursor:pointer;color:inherit;text-align:left}.card:hover,.card:focus-visible{border-color:var(--gold);box-shadow:0 3px 16px #16302b15}.art{height:250px;background:linear-gradient(135deg,#e6e6d9,#fdfbf3);padding:10px 8px 0}.art img{width:100%;height:100%;object-fit:contain}.info{padding:13px 14px}h2{font-family:Songti SC,serif;font-size:17px;margin:0 0 4px}.info p{font-size:12px;color:#73796d;margin:0;min-height:18px}dialog{border:1px solid #ddd6c7;border-radius:16px;background:#fffdf8;color:var(--ink);padding:20px;width:min(94vw,520px);max-height:94vh;overflow:auto}dialog::backdrop{background:#10271fc0}dialog img{width:100%;height:65vh;object-fit:contain}dialog h2{font-size:22px}dialog p{font-size:13px;line-height:1.7}#close{float:right;border:0;background:var(--paper);border-radius:6px;padding:8px 12px;cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--gold);outline-offset:3px}[hidden]{display:none!important}@media(max-width:480px){main{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.art{height:205px}.info{padding:10px}header{padding:24px 16px}h1{font-size:24px}nav{margin-top:16px}dialog img{height:57vh}}
</style><header><h1>银行升职记 · 人物立绘</h1><p>泰和银行的人与事 · 清爽日漫</p></header><nav><input id="search" aria-label="搜索人物" placeholder="搜索姓名或岗位"><select id="group" aria-label="人物分类"><option value="">全部</option><option value="银行">员工与负责人</option><option value="角色">其他人物</option><option value="客户">客户</option><option>玩家</option></select><a href="index.html">进入游戏</a><span id="count"></span></nav><main>'''+''.join(cards)+'''</main><dialog id="detail"><button id="close" aria-label="关闭大图">关闭</button><h2 id="name"></h2><img id="big" alt=""><p id="role"></p><p id="note"></p></dialog><script>
const cards=[...document.querySelectorAll('.card')],search=document.querySelector('#search'),group=document.querySelector('#group'),dialog=document.querySelector('#detail');function filter(){const q=search.value.trim();let n=0;cards.forEach(c=>{c.hidden=(!c.dataset.name.includes(q)&&!c.dataset.role.includes(q))||(group.value&&c.dataset.group!==group.value);if(!c.hidden)n++});document.querySelector('#count').textContent=n+' 张立绘'}search.addEventListener('input',filter);group.addEventListener('change',filter);const initialGroup=new URLSearchParams(location.search).get('group');if([...group.options].some(o=>o.value===initialGroup))group.value=initialGroup;filter();cards.forEach(c=>c.onclick=()=>{document.querySelector('#name').textContent=c.dataset.name;document.querySelector('#role').textContent=c.dataset.role;document.querySelector('#note').textContent=c.dataset.note;const img=document.querySelector('#big');img.src=c.querySelector('img').src;img.alt=c.dataset.name+'立绘';dialog.showModal()});document.querySelector('#close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
</script></html>'''
(root/'portraits.html').write_text(page)
print('Gallery: portraits.html,',len(cards),'portraits')
